head.b:template-skin:
body#layout{background:#f5f5f5!important}
body#layout .site-header,body#layout .site-footer{position:relative!important;background:#fff!important;color:#222!important}
body#layout .hero,body#layout .section{display:none!important}
body#layout .header-row{display:grid!important;grid-template-columns:1fr 2fr;gap:12px;padding:12px!important}
body#layout #header,body#layout #page_list_top,body#layout #page_body,body#layout #footer{
  display:block!important;min-height:70px!important;width:100%!important;margin:10px 0!important;padding:6px!important
}
body#layout main{display:block!important;min-height:180px;padding:12px!important}
body#layout #page_body{display:block!important}

body.script:
//
(function(){
  var chips=[].slice.call(document.querySelectorAll('.chip')),P={d:'PB:',l:'ĐĐ:',t:'HT:'},prefixes=[P.d,P.l,P.t];
  chips.forEach(function(c){var raw=(c.textContent||'').trim();c.setAttribute('data-raw',raw);prefixes.some(function(prefix){if(raw.indexOf(prefix)===0){c.textContent=raw.slice(prefix.length).trim();c.classList.add(prefix===P.d?'chip-department':prefix===P.l?'chip-location':'chip-type');return true}return false})});
  var q=document.getElementById('jobSearch'),d=document.getElementById('departmentFilter'),l=document.getElementById('locationFilter'),t=document.getElementById('typeFilter'),clear=document.getElementById('clearFilters'),count=document.getElementById('jobCount'),empty=document.getElementById('jobsEmpty'),jobs=[].slice.call(document.querySelectorAll('.job'));
  if(!jobs.length||!q||!d||!l||!t||!clear||!count||!empty)return;
  function norm(v){return(v||'').toLocaleLowerCase('vi').trim()}
  function add(select,values){Object.keys(values).sort(function(a,b){return a.localeCompare(b,'vi')}).forEach(function(v){var o=document.createElement('option');o.value=v;o.textContent=v;select.appendChild(o)})}
  function group(prefix){var out={};jobs.forEach(function(job){job.querySelectorAll('.chip').forEach(function(c){var raw=c.getAttribute('data-raw')||'';if(raw.indexOf(prefix)===0){var v=raw.slice(prefix.length).trim();if(v)out[v]=1}})});return out}
  add(d,group(P.d));add(l,group(P.l));add(t,group(P.t));
  function has(job,prefix,value){if(!value)return true;return[].slice.call(job.querySelectorAll('.chip')).some(function(c){return norm(c.getAttribute('data-raw'))===norm(prefix+value)})}
  function run(){var text=norm(q.value),visible=0;jobs.forEach(function(job){var ok=(!text||norm(job.textContent).indexOf(text)>-1)&&has(job,P.d,d.value)&&has(job,P.l,l.value)&&has(job,P.t,t.value);job.style.display=ok?'flex':'none';if(ok)visible++});count.textContent=visible+' vị trí phù hợp';empty.style.display=visible?'none':'block'}
  q.addEventListener('input',run);[d,l,t].forEach(function(x){x.addEventListener('change',run)});clear.addEventListener('click',function(){q.value='';d.value='';l.value='';t.value='';run();q.focus()});run();
})();
//
